from pathlib import Path
import json,re,html

root=Path(__file__).resolve().parents[3]
ux=root/'docs/ux'; ux.mkdir(parents=True,exist_ok=True)
def write(path,text):
    path.parent.mkdir(parents=True,exist_ok=True)
    path.write_text(text.strip()+'\n',encoding='utf-8')
def b(label,target,secondary=False):
    return f'<button class="{"secondary" if secondary else "primary"}" data-go="{target}">{label}</button>'
def card(text,cls=''):
    return f'<div class="card {cls}">{text}</div>'
def money(a='30',s='30'):
    return f'<div class="money"><div><small>Можно потратить</small><strong>{icon("coin")} {a} <span class="sr">монет</span></strong></div><div><small>В копилке</small><strong>{icon("save")} {s} <span class="sr">монет</span></strong></div></div>'
def pet(form=1,palette=1,stage=0):
    c=['#9ed8bb','#f4bf87','#c5b3ed'][palette-1]
    sx=[.78,.9,1][stage]; sy=[.76,.9,1.04][stage]
    extra=['','<path d="M43 74L35 36L67 63M94 63L126 36L117 76"/>','<path d="M62 45L70 17L82 38L96 23L101 49Z"/>'][form-1]
    pattern=['<circle cx="64" cy="113" r="3"/><circle cx="80" cy="122" r="3"/><circle cx="96" cy="113" r="3"/>','<path d="M59 111h42M66 120h28" stroke="#284b40" stroke-width="3"/>','<path d="m80 106 4 7 9 1-6 6 2 8-9-4-8 4 1-8-6-6 9-1z"/>'][palette-1]
    # Same body-relative wrap as Flutter: bounds x=23..137.
    left=23+114*.026; right=137-114*.026; width=right-left
    band=f'M{left+3} 96Q80 106 {right-3} 96L{right} 106Q80 117 {left} 106Z'
    tail=f'M{right-18} 102L{right-5} 101L{right+7} 123L{right-1} 121L{right-6} 128Z'
    uid=f'pet-{form}-{palette}-{stage}-{pet.serial}'; pet.serial+=1
    scarf=''
    if stage:
        stripes=''.join(f'<path d="M{x} 94h7l7 24h-7Z"/>' for x in [left-8+i*width/7 for i in range(9)])
        scarf=f'<defs><clipPath id="{uid}-band"><path d="{band}"/></clipPath><clipPath id="{uid}-tail"><path d="{tail}"/></clipPath></defs><path d="{tail}" fill="#c95049"/><g clip-path="url(#{uid}-tail)" fill="#ffe6a3">'+''.join(f'<rect x="{right-20}" y="{y}" width="30" height="4"/>' for y in range(105,130,9))+f'</g><path d="{tail}" fill="none" stroke="#853e44" stroke-width="1.5"/><path d="{band}" fill="#c95049"/><g clip-path="url(#{uid}-band)" fill="#ffe6a3">{stripes}</g><path d="{band}" fill="none" stroke="#853e44" stroke-width="1.5"/>'
    medal=''
    cape=''
    if stage==2:
        cape='<path d="M37 94Q23 109 19 129Q35 135 49 125L111 125Q130 135 143 127Q137 108 124 94Z" fill="#7661ae" stroke="#ffd776" stroke-width="3"/>'
        medal=f'<path d="{band}" fill="none" stroke="#ffd776" stroke-width="2"/><path d="M{left+18} 95l3 6 7 1-5 5 1 7-6-4-6 4 1-7-5-5 7-1Z" fill="#ffd776" stroke="#853e44" stroke-width="1.5"/><path d="M48 63Q61 51 77 52" fill="none" stroke="#effff4" stroke-width="4" stroke-linecap="round"/>'
    glints='<g fill="white"><circle cx="60" cy="77" r="1.4"/><circle cx="98" cy="77" r="1.4"/></g>' if stage else ''
    label=['Малыш','Подросший','Взрослый'][stage]
    return f'<svg class="pet" viewBox="0 0 160 160" role="img" aria-label="Форма {form}, окраска {palette}, {label}"><g transform="translate({80*(1-sx)} {140*(1-sy)}) scale({sx} {sy})">{cape}<g fill="{c}" stroke="#284b40" stroke-width="3" stroke-linejoin="round">{extra}<path d="M30 90C25 30 135 30 130 90L137 118Q125 132 111 122Q80 146 48 122Q25 132 23 117Z"/></g>{scarf}{medal}<g fill="#284b40"><circle cx="61" cy="78" r="4"/><circle cx="99" cy="78" r="4"/><path d="M71 91Q80 99 89 91" fill="none" stroke="#284b40" stroke-width="3"/>{pattern}</g>{glints}</g></svg>'

pet.serial=0

def icon(kind):
    shapes={
      'home':('<path d="M3 11L12 3L21 11V21H15V14H9V21H3Z"/>','#416ea5'),
      'shop':('<path d="M5 8H19L21 21H3Z"/><path d="M8 8V6a4 4 0 0 1 8 0v2" fill="none" stroke="#713221" stroke-width="2"/>','#db784e'),
      'save':('<rect x="3" y="7" width="18" height="13" rx="6"/><path d="M8 7L8 3L13 7"/><path d="M9 10H15" stroke="#74234e" stroke-width="2"/>','#df84b0'),
      'task':('<path d="M3 4H11V21L3 18ZM13 4H21V18L13 21Z"/>','#438c66'),
      'coin':('<circle cx="12" cy="12" r="10"/><path d="M12 6V18M9 8H14M9 16H14" stroke="#734809" stroke-width="2"/>','#f1ba35'),
      'food':('<path d="M5 3V10Q5 13 8 13V21H10V13Q13 13 13 10V3H11V9H9V3H7V9H5ZM18 3Q14 7 17 13V21H20V3Z"/>','#c66534'),
      'mood':('<circle cx="12" cy="12" r="10"/><circle cx="8" cy="9" r="1.5" fill="#4b2862"/><circle cx="16" cy="9" r="1.5" fill="#4b2862"/><path d="M7 14Q12 20 17 14" fill="none" stroke="#4b2862" stroke-width="2"/>','#c797e7')}
    shape,color=shapes[kind]
    return f'<svg class="icon" viewBox="0 0 24 24" fill="{color}" aria-hidden="true">{shape}</svg>'

