screen('E03','Привет, Финни!','Период 1 · демо',money()+ '<div class="pet-home">'+pet()+'<div><span class="pill">Малыш</span><h3>Радуется</h3><div class="meters"><span title="Сытость" aria-label="Сытость: 75 из 100">'+icon('food')+'75/100</span><span title="Настроение" aria-label="Настроение: 80 из 100">'+icon('mood')+'80/100</span></div></div></div>'+card('<div class="row"><b>Мечта: площадка</b><span>30 / 120</span></div><progress value="30" max="120" aria-label="Накоплено 30 из 120"></progress><small>Осталось накопить 90 монет</small>')+card('<small>Следующее задание</small><b class="block">Сравни план и факт</b>'+b('Попробовать · награда 5','E07'),'accent')+'<div class="grid">'+b('Мой бюджет','E04',True)+b('Прогресс','E09',True)+'</div>'+b('Подвести итог периода','E08',True))
screen('E04','Мой бюджет','Сначала план, потом покупки',money('100','0')+'<p>Распредели монеты. План сам ничего не покупает и не переводит.</p>'+''.join(f'<label class="amount">{name}<input inputmode="numeric" type="number" min="0" value="{v}" aria-label="{name}"></label>' for name,v in [('Нужное',50),('Желания',20),('В копилку',30)])+card('<b>Осталось распределить: 0</b><small class="block">Нужное в этом периоде стоит 50 монет.</small>')+b('Посмотреть план','S_PLAN')+b('Показать план и факт','E08',True))
screen('E05','Покупки','Сначала нужное, затем желания',money()+'<p class="note">Сегодня осталось 1 из 3 покупок. Новые предложения — в следующем периоде.</p>'+''.join(card(f'<div class="row"><b>{name}</b><b>{price} монет</b></div><small>{kind} · {effect}</small>'+b(label,target,True)) for name,price,kind,effect,label,target in [('Полезная еда',30,'Нужное','помогает насытиться','Уже куплено','S_BOUGHT'),('Набор для ухода',20,'Нужное','поднимает настроение','Уже куплено','S_BOUGHT'),('Мяч',35,'Желание','делает игру веселее','Посмотреть покупку','D01'),('Музыкальная игрушка',70,'Желание','радует Финни','Посмотреть покупку','S_FUNDS')]))
screen('E06','Копилка','Маленькие шаги к большой цели',money()+card('<b>Игровая площадка</b><p>30 из 120 монет</p><progress value="30" max="120" aria-label="Накоплено 30 из 120"></progress><small>Ещё 90 — и цель будет достигнута.</small>')+b('Положить монеты','D02')+b('Взять из копилки','S_WITHDRAW',True)+'<h3>Другие мечты</h3>'+card('Велосипедная прогулка · 180 монет')+card('Домашний телескоп · 240 монет')+b('Выбрать другую цель','S_GOAL',True))
