screen('E08','Итог периода','Пример закрытого периода 1',card('<table><thead><tr><th>Монеты</th><th>План</th><th>Факт</th></tr></thead><tbody><tr><td>Нужное</td><td>50</td><td>50</td></tr><tr><td>Желания</td><td>20</td><td>0</td></tr><tr><td>В копилку</td><td>30</td><td>30</td></tr></tbody></table>')+money()+card('<b>Получилось!</b><p>Отложено 30 монет.</p><small>Пройден 1 период · 3 балла заботы.<br>До следующей стадии: 2 периода и 6 баллов.</small>')+b('Начать следующий период','S_NEXT')+b('Посмотреть историю','E09',True))
