states=[('S_FUNDS','Пока не хватает','Музыкальная игрушка стоит 70 монет, а доступно 30. Не хватает 40. Монеты не списаны.','Выбрать другой предмет','E05'),('S_BOUGHT','Уже куплено','Этот предмет уже куплен в текущем периоде. Повторного списания нет.','К покупкам','E05'),('S_PLAN','Подтвердить план?','Нужное 50 · желания 20 · копилка 30. Общая сумма 100. После подтверждения план останется в истории; деньги пока не списываются.','Подтвердить','E03'),('S_WITHDRAW','Взять 10 монет?','Доступно станет 40, в копилке останется 20. До площадки будет не хватать 100. Чистое пополнение периода уменьшится с 30 до 20.','Взять 10 монет','E06'),('S_GOAL','Выбрать телескоп?','Новая цель стоит 240 монет. В копилке останется 30; до цели будет не хватать 210. Деньги не списываются.','Выбрать цель','E06'),('S_DELETE','Удалить профиль?','Имя: Финни · демо. Игра и прогресс этого профиля будут удалены. Другой профиль останется. В приложении потребуется ввести УДАЛИТЬ.','Удалить выбранный профиль','E01'),('S_NEXT','Новый период','Пример: остаток 30 + доход периода 100 = доступно 130. В копилке по-прежнему 30. Теперь составь новый план.','Составить план','E04'),('S_DONE','Пять периодов завершены','Финни вырос! Можно посмотреть результаты. Нового дохода в завершённом демо нет; сброс доступен взрослому.','Посмотреть прогресс','E09'),('S_ERROR','Не удалось сохранить','Не удалось сохранить. Попробуй ещё раз — мы проверим, выполнено ли действие.','Повторить','E03'),('S_STALE','Данные обновились','Суммы изменились. Посмотри их ещё раз перед подтверждением.','Посмотреть заново','D01'),('S_EMPTY','Выберем мечту?','Пока цели нет. В копилке 0 монет. Можно выбрать одну из трёх целей и начать с небольшого взноса.','Выбрать цель','E06'),('S_RETRY','Попробуем ещё раз','Монеты не списаны. Подумай, что нужно для заботы сейчас, а что можно отложить. Осталось 2 попытки.','Вернуться к заданию','T6')]
