tasks=[('Распредели 100 монет','Нужное — хотя бы 50, в копилку — хотя бы 20.','<label>Нужное<input type="number" value="50"></label><label>Желания<input type="number" value="20"></label><label>В копилку<input type="number" value="30"></label>'),('Сравни план и факт','Факт: нужное 50, желания 35, накопления 30. Выбери подходящий план.','<label><input type="radio" name="plan"> План А: 60 / 35 / 20</label><label><input type="radio" name="plan"> План Б: 50 / 35 / 30</label><label><input type="radio" name="plan"> План В: 50 / 45 / 20</label>'),('Составь путь к цели','Цель — 120 монет за 4 периода. В каждом отложи хотя бы 20.',''.join(f'<label>Период {i}<input type="number" value="30"></label>' for i in range(1,5))),('Посчитай накопления','Положили 30, взяли 10, затем положили ещё 5. Сколько осталось отложено?','<div class="choices"><button>25</button><button>35</button><button>45</button></div>'),('Собери корзину','Есть 70 монет. Выбери не более двух предметов, включая еду.',''.join(f'<label><input type="checkbox"> {t}</label>' for t in ['Еда · 30','Уход · 20','Мяч · 35','Музыка · 70'])),('Нужное или желаемое','Для каждого предмета выбери группу.',''.join(f'<label>{t}<select><option>Выбери группу</option><option>Нужное</option><option>Желание</option></select></label>' for t in ['Еда','Уход','Обед','Забота о здоровье','Мяч','Шапочка']))]
for i,(title,prompt,body) in enumerate(tasks,1): screen(f'T{i}',title,'Учебная симуляция · реальные монеты не тратятся','<p>'+prompt+'</p>'+body+b('Посмотреть пример подсказки','S_RETRY')+b('К списку заданий','E07',True)+'<small>Ответы здесь не проверяются. Окончательные варианты придут из контента Л.</small>')

css='''*{box-sizing:border-box}body{margin:0;font:16px/1.45 system-ui,Segoe UI,sans-serif;color:#203e35;background:#e9eee9}button,input,select{font:inherit}button{cursor:pointer;min-height:48px;border-radius:14px;border:1px solid #a9beb0;padding:10px 14px;text-align:center;color:#234438;background:white}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #98521c;outline-offset:3px}button:hover{filter:brightness(.96)}.layout{display:grid;grid-template-columns:260px 1fr;min-height:100vh}aside{padding:28px 20px;background:#203e35;color:#fff}aside h1{font-size:25px;margin:0 0 6px}aside p{color:#d1e5d7;font-size:14px}aside button{display:block;width:100%;margin:6px 0;text-align:left;background:transparent;color:white;border-color:#648476;font-size:14px}aside button.active{background:#e4f1dd;color:#203e35}main{padding:24px;min-width:0}aside{min-width:0}.intro{max-width:760px;margin:0 auto 20px}.intro h2{margin:0;font-size:25px}.intro p{margin:6px 0;color:#52665b;font-size:14px}.stage{display:flex;justify-content:center;align-items:start;gap:24px}.phone{width:360px;max-width:100%;background:#fbfaf4;border:1px solid #bdcbbf;border-radius:28px;overflow:hidden;box-shadow:0 16px 48px #203e3516;flex:none}.status{display:flex;justify-content:space-between;padding:10px 20px 0;font-size:11px;font-weight:700}.top{display:flex;justify-content:space-between;padding:8px 16px;align-items:center}.top button{padding:6px 10px;font-size:14px;background:transparent;border:0}.content{padding:0 16px 16px;min-height:510px}.content h2{font-size:23px;line-height:1.2;margin:6px 0}.subtitle{display:block;color:#51695b;font-size:13px;margin-bottom:14px}.content p{margin:10px 0}.card{background:white;border:1px solid #d4ddd0;border-radius:18px;padding:14px;margin:10px 0}.card p:last-child{margin-bottom:0}.accent{background:#e6f1df;border-color:#c9dabb}.warning{background:#fff2db;border-color:#d5b87e}.primary,.secondary{display:block;width:100%;margin-top:10px;font-weight:600}.primary{background:#285f49;border-color:#285f49;color:white}.secondary{background:#fffefa}.money{display:grid;grid-template-columns:1fr 1fr;gap:10px}.money>div{padding:12px;background:#e7efe3;border-radius:16px}.money strong{display:block;font-size:26px}.money strong span{font-size:12px;font-weight:500}.money small{font-size:12px}.pet{display:block;width:160px;height:135px;margin:8px auto}.pet-home{display:flex;align-items:center;gap:6px}.pet-home .pet{width:135px;height:114px;margin:8px 0}.pet-home h3{margin:5px 0}.pet-home small{font-size:13px}.pill{background:#f5dc9d;border-radius:20px;padding:3px 10px;font-size:12px}small,.note{color:#52695b;font-size:13px}.block{display:block}.row{display:flex;justify-content:space-between;gap:8px;align-items:center}.row span{white-space:nowrap;font-size:13px}progress{width:100%;height:10px;accent-color:#46724e}.grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.choices{display:flex;gap:6px}.choices button{flex:1;font-size:13px;padding:8px 4px}button[aria-pressed=true]{border:2px solid #285f49;background:#e4f1dd}.content label{display:block;margin:12px 0}.content input:not([type=checkbox]):not([type=radio]),select{display:block;width:100%;min-height:48px;padding:10px;border:1px solid #9aaa9d;border-radius:12px;background:white;color:#203e35;margin-top:6px}input[type=checkbox],input[type=radio]{width:22px;height:22px;vertical-align:middle;accent-color:#285f49}.amount{display:flex!important;align-items:center;justify-content:space-between}.amount input{width:104px!important}.switch{padding:10px 0;min-height:48px}fieldset{padding:0;border:0;margin:12px 0}legend{margin-bottom:8px}table{width:100%;border-collapse:collapse}td,th{padding:8px 3px;text-align:left;border-bottom:1px solid #dbe3d7;font-size:14px}.bottom{display:grid;grid-template-columns:repeat(4,1fr);border-top:1px solid #d4ddd0;padding:8px;background:#fffefa}.bottom button{font-size:12px;border:0;padding:8px 3px;background:none}.annotation{max-width:260px;font-size:14px;line-height:1.6}.annotation h3{font-size:16px;margin-top:0}.tag{display:inline-block;padding:3px 8px;background:#dfe9dc;border-radius:8px;font-size:12px}.big{font-size:20px}.big .subtitle,.big small{font-size:16px}.big h2{font-size:28px}.gallery{display:grid;grid-template-columns:repeat(auto-fit,minmax(340px,1fr));gap:24px}.gallery .phone{box-shadow:none}.gallery h3{margin:0 0 8px}.gallery .content{min-height:0}.gallery .phone{border-radius:20px}.gallery .phone button{pointer-events:none}#gallery{display:none}@media(max-width:850px){.layout{grid-template-columns:1fr}aside{padding:14px}aside h1{font-size:20px}#menu{display:flex;overflow:auto;gap:6px}aside button{width:auto;white-space:nowrap}aside p{margin:4px 0}main{padding:12px}.annotation{display:none}.stage{display:block}.phone{margin:auto}.intro h2{font-size:20px}}body.device .layout{display:block}body.device aside,body.device .intro,body.device .annotation{display:none}body.device main{padding:0}body.device .phone{border:0;border-radius:0;width:360px;box-shadow:none}body.device .stage{display:block}@media print{aside,.intro,.stage{display:none!important}#gallery{display:grid!important}.layout{display:block}main{padding:0}.gallery{grid-template-columns:1fr 1fr}.gallery>section{break-inside:avoid}.phone{width:340px;border:1px solid #aaa}.card{break-inside:avoid}body{background:white}}'''
nav=''.join(b(icon(k)+'<span>'+label+'</span>',target,True) for k,label,target in [('home','Дом','E03'),('shop','Покупки','E05'),('save','Копилка','E06'),('task','Задания','E07')])

css += """@font-face{font-family:Pangolin;src:url('../../assets/fonts/Pangolin-Regular.ttf')}@font-face{font-family:Neucha;src:url('../../assets/fonts/Neucha.ttf')}.content h2,.intro h2,aside h1{font-family:Pangolin,sans-serif;font-weight:400}.content h2{font-size:28px}.pill{font-family:Neucha,sans-serif;font-size:21px;background:#e8d3fa;color:#563278}.subtitle{font-family:Neucha,sans-serif;font-size:18px}.phone{background:#fff2d9}.card{background:#e5f4ec;border-color:#b7d8c7}.card:nth-of-type(even){background:#eee3fa;border-color:#d1bde6}.accent{background:#dceefc!important}.primary{background:#6851a5;border-color:#6851a5}.secondary{background:#ffebba;border-color:#bd954d}.money>div{background:#ffe2a2}.money>div+div{background:#f5d5e8}.bottom{background:#e9defb}.bottom button{display:flex;flex-direction:column;align-items:center;gap:3px}.icon{display:inline-block;width:25px;height:25px;flex:none;vertical-align:middle}.money strong{display:flex;align-items:center;gap:7px}.meters{display:flex;flex-direction:column;gap:5px}.meters span{display:flex;align-items:center;gap:6px}.pet,.pet-home .pet{width:140px;height:140px;flex:none;overflow:hidden}.pet-home>div{min-width:0}.sr{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}.growth-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.growth-grid .pet{width:100%;height:auto;margin:0}.growth-grid span{display:block;text-align:center;font-family:Neucha;font-size:18px}"""
screens['E09']['body']='<div class="growth-grid">'+''.join('<div>'+pet(1,1,stage)+'<span>'+label+'</span></div>' for stage,label in enumerate(['Малыш','Подросший','Взрослый']))+'</div>'+screens['E09']['body'].replace(pet(),'')

shell='''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Питомец Финни — макеты v0.3</title><style>CSS</style><body><div class="layout"><aside><h1>Питомец Финни</h1><p>Детский интерфейс v0.3<br>25 сентября 2026</p><div id="menu"></div><button id="all">Все экраны для отчёта</button></aside><main><div class="intro"><span class="tag">Проектирование · тестовые данные</span><h2 id="screenLabel"></h2><p>Кликабельный макет, не Android-приложение. Кнопки показывают заранее подготовленные примеры; деньги и прогресс не рассчитываются и не сохраняются.</p></div><div class="stage"><div class="phone"><div class="status"><span>9:41</span><span>Без сети · ▰</span></div><header class="top"><button id="back" aria-label="Назад">← Назад</button><button data-go="E10" aria-label="Справка">?</button><button data-go="E11">Взрослому</button></header><article id="content" class="content"></article><nav class="bottom" aria-label="Основные разделы">NAV</nav></div><div class="annotation"><h3>Как смотреть</h3><p>Слева выберите экран. Внутри телефона можно переходить кнопками.</p><p>Ширина макета — 360 CSS px. Для увеличенного текста откройте настройки. Длинные страницы прокручиваются.</p><p>Все состояния независимы. Переход между ними не является выполненной игровой операцией.</p><p>Детский дизайн v0.3. Проверки на Android будут позже.</p><button data-go="S_FUNDS">Нехватка монет</button><button data-go="S_STALE">Обновление данных</button><button data-go="S_ERROR">Ошибка сохранения</button><button data-go="S_DONE">Конец демо</button><button data-go="S_EMPTY">Без цели</button><button data-go="E13">Настройки</button></div></div><div id="gallery" class="gallery"></div></main></div><script>const screens=DATA;const pets=PETS;let current='E03',trail=[],form=1,palette=1,big=false;const content=document.getElementById('content');function show(id,remember=true){if(!screens[id])return;if(remember&&current!==id)trail.push(current);current=id;let s=screens[id];document.getElementById('gallery').style.display='none';document.querySelector('.stage').style.display='';content.classList.toggle('big',big);content.innerHTML='<h2>'+s.title+'</h2><span class="subtitle">'+s.sub+'</span>'+s.body;document.getElementById('screenLabel').textContent=id+' · '+s.title;document.querySelectorAll('#menu button').forEach(b=>b.classList.toggle('active',b.dataset.go===id));history.replaceState(null,'','#'+id);document.title=id+' · Финни — макет';if(id==='E02')avatar();if(id==='E13')document.getElementById('bigText').checked=big;window.scrollTo(0,0);}function avatar(){content.querySelector('.pet').outerHTML=pets[form-1][palette-1];content.querySelectorAll('[data-form]').forEach(b=>b.setAttribute('aria-pressed',Number(b.dataset.form)===form));content.querySelectorAll('[data-palette]').forEach(b=>b.setAttribute('aria-pressed',Number(b.dataset.palette)===palette));}document.getElementById('menu').innerHTML=Object.entries(screens).filter(([id])=>id.startsWith('E')||id.startsWith('D')||id.startsWith('T')).map(([id,s])=>'<button data-go="'+id+'">'+id+' · '+s.title+'</button>').join('');document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.go)show(b.dataset.go);if(b.dataset.form){form=Number(b.dataset.form);avatar();}if(b.dataset.palette){palette=Number(b.dataset.palette);avatar();}if(b.id==='back')show(trail.pop()||'E03',false);if(b.id==='adultContinue'){if(document.getElementById('adultAnswer').value==='15')show('E12');else document.getElementById('adultError').textContent='Проверь ответ или попроси взрослого помочь.';}if(b.id==='all'){document.querySelector('.stage').style.display='none';let g=document.getElementById('gallery');g.style.display='grid';g.innerHTML=Object.entries(screens).map(([id,s])=>'<section><h3>'+id+'</h3><div class="phone"><article class="content"><h2>'+s.title+'</h2><span class="subtitle">'+s.sub+'</span>'+s.body+'</article></div></section>').join('');document.getElementById('screenLabel').textContent='Все экраны и состояния · v0.3';}});document.addEventListener('change',e=>{if(e.target.id==='bigText'){big=e.target.checked;content.classList.toggle('big',big);}});window.addEventListener("hashchange",()=>show(location.hash.slice(1),false));if(location.search.includes("device=1")){document.body.classList.add("device");}show(screens[location.hash.slice(1)]?location.hash.slice(1):'E03',false);</script></body></html>'''
shell=shell.replace('CSS',css).replace('NAV',nav).replace('DATA',json.dumps(screens,ensure_ascii=False)).replace('PETS',json.dumps([[pet(f,p) for p in range(1,4)]for f in range(1,4)],ensure_ascii=False))
write(ux/'prototype-v0.1.html',shell)
write(ux/'screen-index.json',json.dumps({k:{'title':v['title'],'subtitle':v['sub']}for k,v in screens.items()},ensure_ascii=False,indent=2))
write(ux/'assets/pet-variants.svg','<svg xmlns="http://www.w3.org/2000/svg" width="540" height="540" viewBox="0 0 540 540"><rect width="540" height="540" fill="#fbfaf4"/>'+''.join(f'<g transform="translate({(p-1)*180+10},{(f-1)*180+10})">'+pet(f,p).replace('class="pet"','width="160" height="135"')+f'<text x="80" y="158" text-anchor="middle" font-family="sans-serif" font-size="12">Форма {f} · окраска {p}</text></g>'for f in range(1,4)for p in range(1,4))+'</svg>')
print(f'Generated {len(screens)} screens and states in {ux}')

write(ux/'pet-growth.html','<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Как растёт Финни</title><style>'+css+'body{padding:24px;background:#fff2d9}.growth-grid{max-width:680px}.growth-grid .pet{max-width:190px}h1,h2{font-family:Pangolin;font-weight:400}</style><h1>Как растёт Финни</h1><p>Три формы, три окраски, три стадии. Стадию выбирает игровая логика.</p>'+''.join('<h2>Форма '+str(f)+' · окраска '+str(p)+'</h2><div class="growth-grid">'+''.join('<div>'+pet(f,p,t)+'<span>'+label+'</span></div>' for t,label in enumerate(['Малыш','Подросший','Взрослый']))+'</div>' for f in range(1,4) for p in range(1,4))+'</html>')
